-- Let me check what "temperature problems" means - look at records where tempnowc exceeds some threshold
-- or where there are temperature-related alerts. Also check if there's a pattern with alertkind = 'Temperature'
SELECT alertkind, COUNT(*) FROM sensordata GROUP BY alertkind ORDER BY COUNT(*) DESC;

-- Let me check records where tempnowc > storetempc (high temperature condition)
-- and also ABS(tempnowc - storetempc) > temptolc (exceeds tolerance)
SELECT COUNT(*) FROM sensordata WHERE tempnowc > storetempc + temptolc;

-- Let me check: records with temp problems could mean tempnowc > storetempc (high temp) 
-- AND deviation exceeds tolerance. These would be "High Temp Breach" candidates
SELECT COUNT(*) FROM sensordata WHERE tempnowc > storetempc AND ABS(tempnowc - storetempc) > temptolc;
